import { RadioGroup } from "vaiperui";

<RadioGroup
  label="Plan"
  defaultValue="free"
  onValueChange={(plan) => console.log(plan)}
  options={[
    { value: "free", label: "Free", description: "For side projects" },
    { value: "pro", label: "Pro", description: "For small teams" },
    { value: "team", label: "Team", disabled: true },
  ]}
/>

import { Slider } from "vaiperui";

const [volume, setVolume] = useState([40]);
const [price, setPrice] = useState([200, 800]);

<p>Volume: {volume[0]}%</p>
<Slider aria-label="Volume" value={volume} onValueChange={setVolume} />

<Slider
  aria-label="Price"
  thumbLabels={["Minimum price", "Maximum price"]}
  value={price}
  onValueChange={setPrice}
  min={0}
  max={1000}
  step={10}
/>

import { Upload } from "vaiperui";

const [files, setFiles] = useState<File[]>([]);

<Upload
  multiple
  accept=".pdf,image/*"
  label="Attachments"
  description="PDF or image, up to 5 MB"
  onFilesChange={(chosen) => setFiles((current) => [...current, ...chosen])}
/>

import { Calendar } from "vaiperui";

const [date, setDate] = useState<Date>();
const [period, setPeriod] = useState<DateRange>({});

<Calendar value={date} onValueChange={setDate} />
<Calendar mode="range" value={period} onValueChange={setPeriod} />

import { DatePicker } from "vaiperui";

const [date, setDate] = useState<Date>();

<DatePicker label="Delivery date" value={date} onValueChange={setDate} />
<DatePicker
  label="Delivery date"
  minDate={new Date()}
  weekStartsOn={1}
  locale="en-US"
/>

import { DateRangePicker, getDatePresets, type DateRange } from "vaiperui";

const [period, setPeriod] = useState<DateRange>({});

<DateRangePicker label="Stay" presets value={period} onValueChange={setPeriod} />

// Custom list, translated labels
<DateRangePicker presets={[
  ...getDatePresets({ today: "Today" }).slice(0, 3),
  { label: "Q4", range: { from: new Date(2026, 9, 1), to: new Date(2026, 11, 31) } },
]} />

import { TimePicker } from "vaiperui";

const [time, setTime] = useState("14:30");

<TimePicker label="Time" value={time} onValueChange={setTime} />
<TimePicker label="Time" hour12 minuteStep={15} />

import { DateTimePicker } from "vaiperui";

const [when, setWhen] = useState<Date>();

<DateTimePicker label="Appointment" value={when} onValueChange={setWhen} />
<DateTimePicker label="Appointment" hour12 minuteStep={15} minDate={new Date()} />

import { Badge } from "vaiperui";

<Badge status="success" dot>Active</Badge>
<Badge status="warning">Attention</Badge>

import { List, ListItem, Avatar, Badge } from "vaiperui";

<List divided>
  <ListItem
    leading={<Avatar name="Camila Souza" />}
    title="Camila Souza"
    description="Product designer"
    trailing={<Badge status="success">Active</Badge>}
  />
</List>

